<?php
declare(strict_types=1);
require __DIR__ . '/src/bootstrap.php';
$msg='';
if(isset($_GET['logout'])){Auth::logout();header('Location: '.url('admin.php'));exit;}
if(!Auth::check()){
 if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); if(Auth::login($db,trim($_POST['email']??''),$_POST['password']??'')){header('Location: '.url('admin.php'));exit;} $msg='Login inválido.';}
 ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=h(url('assets/app.css'))?>"><title>Admin Farmácia</title></head><body><main class="wrap narrow"><h1>Admin · Farmácia</h1><?php if($msg):?><div class="flash"><?=h($msg)?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="email" name="email" placeholder="E-mail" required><input type="password" name="password" placeholder="Senha" required><button>Entrar</button></form></main></body></html><?php exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';
 if($action==='med_update'){$id=(int)$_POST['id'];$st=$db->prepare('UPDATE medications SET price=?,stock=?,image_url=?,requires_prescription=?,retain_prescription=?,controlled=?,sell_online=?,review_required=0,updated_at=CURRENT_TIMESTAMP WHERE id=?');$st->execute([(float)($_POST['price']??0),(int)($_POST['stock']??0),trim($_POST['image_url']??''),isset($_POST['requires_prescription'])?1:0,isset($_POST['retain_prescription'])?1:0,isset($_POST['controlled'])?1:0,isset($_POST['sell_online'])?1:0,$id]);Catalog::audit($db,'medication.updated','medication',(string)$id);$msg='Medicamento atualizado.';}
 if($action==='order_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'pending';$allowed=['pending','approved','rejected','separating','ready','delivered','cancelled'];if(in_array($status,$allowed,true)){$st=$db->prepare('UPDATE orders SET status=?, pharmacist_status=?, updated_at=CURRENT_TIMESTAMP WHERE id=?');$ph=$status==='approved'?'approved':($status==='rejected'?'rejected':'awaiting_review');$st->execute([$status,$ph,$id]);Catalog::audit($db,'order.status','order',(string)$id,['status'=>$status]);$msg='Pedido atualizado.';}}
}
if(($_GET['action']??'')==='prescription'){Auth::require();$id=(int)($_GET['id']??0);$st=$db->prepare('SELECT prescription_path FROM orders WHERE id=?');$st->execute([$id]);$row=$st->fetch();if(!$row||!is_file($row['prescription_path'])){http_response_code(404);exit('Arquivo não encontrado');}$ext=strtolower(pathinfo($row['prescription_path'],PATHINFO_EXTENSION));header('Content-Type: '.($ext==='pdf'?'application/pdf':($ext==='png'?'image/png':'image/jpeg')));header('Content-Disposition: inline; filename="receita_'.$id.'.'.$ext.'"');readfile($row['prescription_path']);exit;}
$q=trim($_GET['q']??'');$meds=$q!==''?Catalog::search($db,$q,30):[];$orders=$db->query('SELECT * FROM orders ORDER BY id DESC LIMIT 30')->fetchAll();$counts=['meds'=>(int)$db->query('SELECT COUNT(*) FROM medications')->fetchColumn(),'review'=>(int)$db->query('SELECT COUNT(*) FROM medications WHERE review_required=1')->fetchColumn(),'orders'=>(int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'rx'=>(int)$db->query("SELECT COUNT(*) FROM orders WHERE pharmacist_status='awaiting_review'")->fetchColumn()];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=h(url('assets/app.css'))?>"><title>Admin Farmácia</title></head><body><header><div class="wrap top"><strong>Admin · Farmácia</strong><nav><a href="<?=h(url())?>">Loja</a><a href="?logout=1">Sair</a></nav></div></header><main class="wrap"><?php if($msg):?><div class="flash"><?=h($msg)?></div><?php endif;?><div class="stats"><div><b><?=$counts['meds']?></b><span>Medicamentos</span></div><div><b><?=$counts['review']?></b><span>A revisar</span></div><div><b><?=$counts['orders']?></b><span>Pedidos</span></div><div><b><?=$counts['rx']?></b><span>Receitas pendentes</span></div></div><section class="panel"><h2>Revisar catálogo</h2><form method="get" class="inline"><input name="q" value="<?=h($q)?>" placeholder="Buscar medicamento"><button>Buscar</button></form><?php foreach($meds as $m):?><form method="post" class="adminrow"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="med_update"><input type="hidden" name="id" value="<?=$m['id']?>"><div><b><?=h($m['product_name'])?></b><small><?=h($m['active_ingredient'])?> · <?=h($m['registration'])?></small></div><input name="price" type="number" step="0.01" value="<?=h($m['price'])?>" placeholder="Preço"><input name="stock" type="number" value="<?=h($m['stock'])?>" placeholder="Estoque"><input name="image_url" value="<?=h($m['image_url'])?>" placeholder="URL imagem licenciada"><label><input type="checkbox" name="requires_prescription" <?=((int)$m['requires_prescription'])?'checked':''?>> Receita</label><label><input type="checkbox" name="retain_prescription" <?=((int)$m['retain_prescription'])?'checked':''?>> Retém</label><label><input type="checkbox" name="controlled" <?=((int)$m['controlled'])?'checked':''?>> Controlado</label><label><input type="checkbox" name="sell_online" <?=((int)$m['sell_online'])?'checked':''?>> Venda remota</label><button>Salvar</button></form><?php endforeach;?></section><section class="panel"><h2>Pedidos recentes</h2><?php foreach($orders as $o):?><div class="orderrow"><div><b>#<?=$o['id']?> · <?=h($o['customer_name'])?></b><small><?=h($o['customer_email'])?> · R$ <?=number_format((float)$o['total'],2,',','.')?> · <?=h($o['created_at'])?></small><?php if($o['prescription_path']):?><a target="_blank" href="?action=prescription&id=<?=$o['id']?>">Ver receita</a><?php endif;?></div><form method="post" class="inline"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','approved','rejected','separating','ready','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$o['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button>Atualizar</button></form></div><?php endforeach;?></section></main></body></html>
